def solution(text):
    """Rotates printable ASCII characters by 24 positions."""
    out = []
    for ch in text:
        o = ord(ch)
        if 32 <= o <= 126:
            out.append(chr(32 + ((o - 32 + 24) % 95)))
        else:
            out.append(ch)
    return ''.join(out)
